import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷三·24","description":"易小帖 - 卷三·24","frontmatter":{"title":"卷三·24","description":"易小帖 - 卷三·24"},"headers":[],"relativePath":"zh/classics/yixiaotie/092.md","filePath":"zh/classics/yixiaotie/092.md"}'),o={name:"zh/classics/yixiaotie/092.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷三·24",tabindex:"-1"},[r("卷三·24 "),e("a",{class:"header-anchor",href:"#卷三·24","aria-label":"Permalink to “卷三·24”"},"​")],-1),e("p",null,"範諤昌疑《彖傳》非孔子作，以乾《彖傳》大哉乾元諸語《文言》又從而讚之，如時乘六龍以御天也，雲行雨施，天下平也。夫子不應自讚其語。然明夷《彖傳》直以文王箕子對衍作彖，則謂之文周舊文，不得矣。若謂諸《象傳》今所稱大象、小象者皆周公作，則更不然。從來一卦總名，原有卦辭，如《春秋傳》史墨對趙簡子曰「在易卦雷乘乾曰大壯」，類此即大象也。亦皆有每爻小象辭，如陳文子斷困之大過，引困象辭曰「困於石，往不濟也；據於蒺藜，所恃傷也。入於其宮不見其妻凶，無所歸也」，類此即小象也。緣此時，孔子大小象辭俱未見於世，而在夫子之先，又必先有大小象辭，一如夫子所讚例，故云云。若周公原文，則凡《春秋傳》卜筮所引，必早及之矣。夫子十翼，其數目雖互有參錯，然其雲夫子作，則自漢迄今無異詞者。宋去古甚遠，何足知之。諤昌陳摶門人。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
